import numpy as np
import xarray as xr
from satpy.scene import Scene
from satpy.readers import AbstractYAMLReader
from satpy.dataset import DatasetDict
from unittest.mock import MagicMock
from satpy.dependency import ReaderNode

class MockReader(AbstractYAMLReader):
    def load(self, dataset_keys, **kwargs):
        if kwargs.get('test_arg') != 'test_val':
            raise RuntimeError(f"Expected test_arg='test_val', got {kwargs}")

        datasets = DatasetDict()
        for key in dataset_keys:
            datasets[key] = xr.DataArray(np.random.rand(10, 10), name=key)
        return datasets

    def available_dataset_ids(self):
        return {'test_ds'}

    def get_dataset_key(self, ds_key):
        return ds_key

def test_scene_load_kwargs():
    scene = Scene()
    mock_reader = MockReader()
    scene._readers = {'mock_reader': mock_reader}

    # Mock the dependency tree to return a node for 'test_ds'
    node = ReaderNode('test_ds', 'mock_reader')

    scene._dependency_tree = MagicMock()
    scene._dependency_tree.leaves.return_value = {node}
    scene.missing_datasets = {'test_ds'}

    # Mock _update_dependency_tree to avoid sensor config loading
    scene._update_dependency_tree = MagicMock()

    # Mock generate_possible_composites to avoid further processing
    scene.generate_possible_composites = MagicMock()

    # Now call Scene.load
    scene.load(['test_ds'], test_arg='test_val')
    print("Success!")

if __name__ == "__main__":
    try:
        test_scene_load_kwargs()
    except Exception as e:
        import traceback
        traceback.print_exc()
        exit(1)

